    def calculate_score(solved):
        base = sum(problems[i][0] for i in range(D) if solved[i])
        perfect = sum(problems[i][1] for i in range(D) if solved[i] == problems[i][0])
        return base + perfect

    def dfs(index, solved):
        if index == D:
            return calculate_score(solved)

        score = float('inf')
        for i in range(problems[index][0] + 1):
            new_solved = solved[:]
            new_solved[index] = i
            score = min(score, dfs(index + 1, new_solved))

        return score

    min_problems = dfs(0, [0] * D)
