import sys

def min_problems_to_achieve_score(D, G, p, c):
    def can_achieve(score):
        total_problems = 0
        for i in range(D):
            if score >= 100 * (i + 1) * (p[i] + 1):
                score += c[i]
                total_problems += p[i] + 1
            else:
                problems_needed = (score - 100 * (i + 1) + 100 * (i + 1) * p[i]) // (100 * (i + 1))
                if problems_needed > p[i]:
                    return False
                total_problems += problems_needed
                score += problems_needed * 100 * (i + 1)
            if score >= G:
                return True
        return False

    left, right = 0, sum(p)
    while left < right:
        mid = (left + right) // 2
        if can_achieve(mid):
            right = mid
        else:
            left = mid + 1

    return left

